using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;
namespace Decont;
public class Db(DbContextOptions<Db> options):IdentityDbContext<User>(options) {
 public DbSet<Report> Reports=>Set<Report>();public DbSet<Line> Lines=>Set<Line>();public DbSet<Evidence> Evidence=>Set<Evidence>();public DbSet<Snapshot> Snapshots=>Set<Snapshot>();public DbSet<Decision> Decisions=>Set<Decision>();public DbSet<Audit> Audits=>Set<Audit>();public DbSet<Master> Masters=>Set<Master>();public DbSet<VendorRequest> Vendors=>Set<VendorRequest>();public DbSet<CardTransaction> Transactions=>Set<CardTransaction>();public DbSet<Match> Matches=>Set<Match>();public DbSet<Batch> Batches=>Set<Batch>();public DbSet<Notice> Notices=>Set<Notice>();public DbSet<Job> Jobs=>Set<Job>();public DbSet<Delegation> Delegations=>Set<Delegation>();public DbSet<Session> Sessions=>Set<Session>();public DbSet<Review> Reviews=>Set<Review>();public DbSet<Idempotency> Idempotencies=>Set<Idempotency>();
 protected override void OnModelCreating(ModelBuilder b){base.OnModelCreating(b);b.Entity<Report>().HasIndex(r=>r.Number).IsUnique();b.Entity<Report>().Property(r=>r.Version).IsConcurrencyToken();b.Entity<Report>().HasMany(r=>r.Lines).WithOne().HasForeignKey(l=>l.ReportId).OnDelete(DeleteBehavior.Restrict);b.Entity<Line>().HasMany(l=>l.Evidence).WithOne().HasForeignKey(a=>a.LineId).OnDelete(DeleteBehavior.Restrict);b.Entity<Snapshot>().HasIndex(s=>new{s.ReportId,s.Revision}).IsUnique();b.Entity<Master>().HasIndex(m=>new{m.Kind,m.Code,m.From}).IsUnique();b.Entity<VendorRequest>().HasIndex(v=>new{v.ReportId,v.Cui}).IsUnique();b.Entity<CardTransaction>().HasIndex(t=>new{t.CardId,t.Reference}).IsUnique();b.Entity<Batch>().HasIndex(e=>new{e.ReportId,e.Cycle}).IsUnique();b.Entity<Idempotency>().HasKey(x=>x.Id);b.Entity<Snapshot>().HasOne<Report>().WithMany().HasForeignKey(x=>x.ReportId).OnDelete(DeleteBehavior.Restrict);b.Entity<Decision>().HasOne<Report>().WithMany().HasForeignKey(x=>x.ReportId).OnDelete(DeleteBehavior.Restrict);b.Entity<Review>().HasOne<Report>().WithMany().HasForeignKey(x=>x.ReportId).OnDelete(DeleteBehavior.Restrict);b.Entity<Batch>().HasOne<Report>().WithMany().HasForeignKey(x=>x.ReportId).OnDelete(DeleteBehavior.Restrict);b.Entity<Match>().HasOne<Line>().WithMany().HasForeignKey(x=>x.LineId).OnDelete(DeleteBehavior.Restrict);b.Entity<Match>().HasOne<CardTransaction>().WithMany().HasForeignKey(x=>x.TransactionId).OnDelete(DeleteBehavior.Restrict);b.Entity<Session>().HasOne<User>().WithMany().HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Cascade);foreach(var entity in b.Model.GetEntityTypes())foreach(var property in entity.GetProperties())if(property.ClrType==typeof(decimal)||property.ClrType==typeof(decimal?)){property.SetPrecision(20);property.SetScale(6);}}
 public override Task<int> SaveChangesAsync(CancellationToken ct=default){foreach(var entry in ChangeTracker.Entries())if((entry.Entity is Audit or Snapshot or Decision or Review) && (entry.State is EntityState.Modified or EntityState.Deleted))throw new InvalidOperationException("Immutable evidence");return base.SaveChangesAsync(ct);}
}
